solutionCode:
pub fn o_veredito_do(resposta: Result<i32, String>) -> String {
    match resposta {
        Ok(n) => format!("nota: {}", n),
        Err(motivo) => format!("sem nota: {}", motivo),
    }
}

testsCode:
use desafio::o_veredito_do;

#[test]
fn testa_o_veredito_da_nota_oito() {
    assert_eq!(o_veredito_do(Ok(8)), String::from("nota: 8"));
}

#[test]
fn testa_o_veredito_da_falta_de_resposta() {
    assert_eq!(o_veredito_do(Err(String::from("falta resposta"))), String::from("sem nota: falta resposta"));
}
